    """A linear combination of Weyl strings with complex coefficients."""

    def __init__(self, terms: dict[WeylString, complex] | None = None):
        self._terms: dict[WeylString, complex] = dict(terms or {})

    def add(self, term: WeylString, coeff: complex) -&gt; None:
        self._terms[term] = self._terms.get(term, 0j) + coeff

    def scale(self, factor: complex) -&gt; None:
        for key in self._terms:
            self._terms[key] *= factor

    def merge(self, other: "WeylTermSum") -&gt; None:
        for key, coeff in other.items():
            self.add(key, coeff)

    def truncate(self, policy) -&gt; None:
        for truncator in policy:
            if isinstance(truncator, WeightTruncator):
                limit = truncator.weight
                self._terms = {k: c for k, c in self._terms.items() if k.weight &lt;= limit}
            elif isinstance(truncator, CoefficientTruncator):
                floor = truncator.coefficient
                self._terms = {k: c for k, c in self._terms.items() if abs(c) &gt; floor}
            else:
                raise TypeError(f"unsupported truncator: {truncator!r}")

    def items(self) -&gt; list[tuple[WeylString, complex]]:
        return list(self._terms.items())

    def __len__(self) -&gt; int:
        return len(self._terms)

    @classmethod
    def hermitian(cls, term: WeylString, coeff: complex = 1.0) -&gt; "WeylTermSum":
        """$\\tfrac{1}{2}(cW + \\overline{c}W^\\dagger)$: the Hermitian observable built from one string."""
        out = cls({term: 0.5 * coeff})
        phase, inv = term.dagger()
        out.add(inv, 0.5 * np.conj(coeff) * phase)
        return out


