class WeylPropagator(AbstractPropagator):
    """Heisenberg propagation of Weyl observables through qudit circuits."""

    def __init__(self, noise=None, truncation=None):
        self.set_noise(noise)
        self.set_truncation(truncation)

    @property
    def noise(self):
        return self._noise

    def set_noise(self, noise=None) -&gt; None:
        self._noise = noise

    @property
    def truncators(self) -&gt; list[object]:
        return self._truncators

    def set_truncation(self, truncation=None) -&gt; None:
        if truncation is None:
            truncation = []
        elif not isinstance(truncation, (list, tuple)):
            truncation = [truncation]
        self._truncators = list(truncation)

    @property
    def _weight_cutoff(self) -&gt; int | None:
        limits = [t.weight for t in self._truncators if isinstance(t, WeightTruncator)]
        return min(limits) if limits else None

    @property
    def _coefficient_floor(self) -&gt; float:
        floors = [t.coefficient for t in self._truncators if isinstance(t, CoefficientTruncator)]
        return max(floors) if floors else 0.0

    def _apply(self, terms: WeylTermSum, rot: WeylRotation) -&gt; WeylTermSum:
        max_weight, floor, noise = self._weight_cutoff, self._coefficient_floor, self._noise
        out: dict[WeylString, complex] = {}
        for key, coeff in terms.items():
            for child, child_coeff in conjugate(key, coeff, rot):
                if max_weight is not None and child.weight &gt; max_weight:
                    continue
                if abs(child_coeff) &lt;= floor:
                    continue
                if noise is not None:
                    child_coeff *= noise.damping_factor(child.weight, 0)
                out[child] = out.get(child, 0j) + child_coeff
        if floor:
            out = {k: c for k, c in out.items() if abs(c) &gt; floor}
        return WeylTermSum(out)

    def propagate(self, observable: WeylTermSum, circuit: list[WeylRotation], filename=None):
        """Back-propagate ``circuit`` through ``observable``, returning $U^\\dagger O U$."""
        if filename is not None:
            raise NotImplementedError("term I/O is out of scope for this notebook")
        terms, counts = WeylTermSum(dict(observable.items())), [len(observable)]
        for rot in reversed(circuit):  # Heisenberg: last gate acts on the observable first
            terms = self._apply(terms, rot)
            counts.append(len(terms))
        self._last_counts = counts
        return terms

    def expectation_value(self, observable, circuit, initial_state=0, filename=None):
        """$\\langle f | U^\\dagger O U | f\\rangle$ for a computational basis state $|f\\rangle$."""
        terms = self.propagate(observable, circuit, filename)
        n, d = (observable.items()[0][0].n_qudits, observable.items()[0][0].d)
        if isinstance(initial_state, int):
            fock = tuple((initial_state // d**k) % d for k in range(n))
        else:
